# Generates apps/api/internal/adminwrites/testdata/profiles.cases.json (the profile banner and profile character
# write cases) and profiles.seed.sql. The cases are data; profiles.golden.json is captured from the TypeScript by
# capture-writes-profiles.test.mjs, never generated here. Edit this file, run
# `python3 apps/api/testdata/tools/gen-writes-admin-profiles-cases.py`, then rerun the capture.
#
# POST /api/profile-banners and POST /api/profile-characters upload a picture (a data URL goes to Supabase Storage),
# so they are not ported here: the pictures track owns them.
import json
import os

HERE = os.path.dirname(os.path.abspath(__file__))
OUT = os.path.join(HERE, "../../internal/adminwrites/testdata")
OWNER = "ad100000-0000-4000-8000-000000000001"
SECOND = "ad100000-0000-4000-8000-000000000002"
FORMER = "ad100000-0000-4000-8000-000000000003"
UNKNOWN = "ad100000-0000-4000-8000-0000000000ff"

B = lambda n: "b1000000-0000-4000-8000-%012d" % n   # uploaded banners
C = lambda n: "c1000000-0000-4000-8000-%012d" % n   # uploaded characters
SVG = "data:image/svg+xml,%3Csvg%2F%3E"

# ---------------------------------------------------------------- seed
banners = [  # id, image, shown, deleted, default
    ("court", "", True, False, True),
    ("night", "", True, False, False),
    ("dusk", "", True, False, False),
    ("ember", "", False, False, False),
    ("sun", "", False, False, False),
    ("stripe", "", True, True, False),
    (B(1), "https://cdn.example.test/profile-banners/b1.webp", True, False, False),
    (B(2), "https://cdn.example.test/profile-banners/b2.png", False, False, False),
    (B(3), "https://cdn.example.test/profile-banners/b3.jpg", False, True, False),
]
letters = [""] + [chr(c) for c in range(ord("a"), ord("p") + 1)]
characters = [(i, SVG, True, False) for i in letters] + [  # id, image, shown, deleted
    (C(1), "https://cdn.example.test/profile-characters/c1.webp", True, False),
    (C(2), "https://cdn.example.test/profile-characters/c2.png", False, False),
    (C(3), "https://cdn.example.test/profile-characters/c3.jpg", True, True),
]
q = lambda s: "'" + s.replace("'", "''") + "'"
lines = [
    "-- Fictional admins, a profile banner library and a profile character library for the Admin writes",
    "-- characterization of the banner and character routes. Applied on top of the Prisma migrations (which seed the",
    "-- six banners and 24 characters, so this file replaces them). Accounts are linked with auth_provider 'supabase'",
    "-- (the TypeScript side); the Go test relinks them to its own sign-in identities. Foreign key checks and",
    "-- triggers are off for this load. The file is also the reset between cases, so it removes what it inserts.",
    "-- GENERATED by apps/api/testdata/tools/gen-writes-admin-profiles-cases.py: edit that, not this.",
    "BEGIN;",
    "SET LOCAL session_replication_role = replica;",
    "",
    "DELETE FROM player_notifications;",
    "DELETE FROM admin_audit_events;",
    "DELETE FROM profile_banners;",
    "DELETE FROM profile_characters;",
    "DELETE FROM admin_accounts;",
    "",
    "INSERT INTO admin_accounts (id, auth_provider, auth_subject, active, display_name, updated_at) VALUES",
    "  ('ad000000-0000-4000-8000-000000000001', 'supabase', 'ad100000-0000-4000-8000-000000000001', true, 'Owner', now()),",
    "  ('ad000000-0000-4000-8000-000000000002', 'supabase', 'ad100000-0000-4000-8000-000000000002', true, 'Second Admin', now()),",
    "  ('ad000000-0000-4000-8000-000000000003', 'supabase', 'ad100000-0000-4000-8000-000000000003', false, 'Former Admin', now());",
    "",
    "-- ---- banners: court is the default; 4 are shown and live (court, night, dusk, the first upload); stripe and the",
    "--      third upload are deleted ----",
    "INSERT INTO profile_banners (id, image, shown, uploaded_at, number, deleted_at, is_default) VALUES",
]
rows = []
for n, (i, img, shown, deleted, default) in enumerate(banners):
    rows.append("  (%s, %s, %s, TIMESTAMPTZ '2026-11-11 00:00:00+00' + %d * INTERVAL '1 millisecond', %d, %s, %s)" % (
        q(i), q(img), str(shown).lower(), n, n + 1,
        "TIMESTAMPTZ '2026-11-15 09:00:00+00'" if deleted else "NULL", str(default).lower()))
lines.append(",\n".join(rows) + ";")
lines += ["", "-- ---- characters: '' and a to p (17, the first is the one with the empty id), then 3 uploads; 18 are shown and",
          "--      live; the third upload is deleted ----",
          "INSERT INTO profile_characters (id, image, shown, uploaded_at, number, deleted_at) VALUES"]
rows = []
for n, (i, img, shown, deleted) in enumerate(characters):
    rows.append("  (%s, %s, %s, TIMESTAMPTZ '2026-11-09 00:00:00+00' + %d * INTERVAL '1 millisecond', %d, %s)" % (
        q(i), q(img), str(shown).lower(), n, n + 1,
        "TIMESTAMPTZ '2026-11-15 09:00:00+00'" if deleted else "NULL"))
lines.append(",\n".join(rows) + ";")
lines += ["", "COMMIT;", ""]
open(os.path.join(OUT, "profiles.seed.sql"), "w").write("\n".join(lines))

# ---------------------------------------------------------------- cases
cases = []
def case(name, steps, scenario="base", redact=None):
    c = {"name": name, "scenario": scenario, "steps": steps}
    if redact: c["redact"] = redact
    cases.append(c)

def step(method, path, body=None, who=OWNER, raw=None, **kw):
    s = {"method": method, "path": path, "who": who}
    if raw is not None: s["rawBody"] = raw
    elif body is not None: s["body"] = body
    s.update(kw)
    return s

bp = lambda i="": "/api/profile-banners/" + i
cp = lambda i: "/api/profile-characters/" + i   # the empty id travels as "_"
patch = lambda path, shown="__absent__", **kw: step("PATCH", path, None if shown == "__absent__" else {"shown": shown}, **kw)
delete = lambda path, **kw: step("DELETE", path, **kw)
restore = lambda path, **kw: step("POST", path + "/restore", **kw)
default = lambda path, **kw: step("POST", path + "/default", **kw)

# ---- guards (the pass check comes before the body, the id and the library) ----
for n, s in [
    ("banner_patch", patch(bp("night"), False, who=None)),
    ("banner_delete", delete(bp("night"), who=None)),
    ("banner_restore", restore(bp("stripe"), who=None)),
    ("banner_default", default(bp("night"), who=None)),
    ("character_patch", patch(cp("a"), False, who=None)),
    ("character_delete", delete(cp("a"), who=None)),
    ("character_restore", restore(cp(C(3)), who=None)),
]:
    case("guard_no_session_" + n, [s])
for n, mk in [
    ("banner_patch", lambda w, **kw: patch(bp("night"), False, who=w, **kw)),
    ("banner_delete", lambda w, **kw: delete(bp("night"), who=w, **kw)),
    ("banner_restore", lambda w, **kw: restore(bp("stripe"), who=w, **kw)),
    ("banner_default", lambda w, **kw: default(bp("night"), who=w, **kw)),
    ("character_patch", lambda w, **kw: patch(cp("a"), False, who=w, **kw)),
    ("character_delete", lambda w, **kw: delete(cp("a"), who=w, **kw)),
    ("character_restore", lambda w, **kw: restore(cp(C(3)), who=w, **kw)),
]:
    case("guard_former_admin_" + n, [mk(FORMER, goExpects={"status": 401, "code": "unauthenticated"})])
case("guard_unknown_subject_banner_patch", [patch(bp("night"), False, who=UNKNOWN, goExpects={"status": 401, "code": "unauthenticated"})])
case("guard_beats_a_bad_body", [patch(bp("night"), raw="not json", who=None)])

# ---- banners: PATCH (show and hide) ----
case("banner_hide_one", [patch(bp("dusk"), False)])
case("banner_show_one", [patch(bp("ember"), True)])
case("banner_hide_by_the_second_admin", [patch(bp("dusk"), False, who=SECOND)])
case("banner_hide_an_upload", [patch(bp(B(1)), False)])
case("banner_show_an_upload", [patch(bp(B(2)), True)])
case("banner_hide_then_show_again", [patch(bp("dusk"), False), patch(bp("dusk"), True)])
case("banner_same_value_changes_nothing", [patch(bp("night"), True), patch(bp("ember"), False)])
case("banner_hide_the_default_is_refused", [patch(bp("court"), False)])
case("banner_hide_a_shown_one_at_the_minimum_is_refused", [patch(bp("night"), False)], scenario="two_shown")
case("banner_the_default_refusal_comes_first", [patch(bp("court"), False)], scenario="two_shown")
case("banner_hide_a_shown_one_above_the_minimum", [patch(bp("night"), False)], scenario="three_shown")
case("banner_hide_down_to_the_minimum", [patch(bp("dusk"), False), patch(bp("night"), False), patch(bp(B(1)), False)])
case("banner_show_at_the_minimum", [patch(bp("ember"), True)], scenario="two_shown")
case("banner_hide_follows_the_new_default", [patch(bp("night"), False), patch(bp("court"), False)], scenario="night_default")
case("banner_unknown_id", [patch(bp("nope"), True)])
case("banner_deleted_id", [patch(bp("stripe"), True), patch(bp(B(3)), True)])
case("banner_id_formats_are_not_in_the_library", [patch(bp(i), True) for i in ["Court", "has-dash", "a" * 25, "a" * 24, B(1).upper(), "b1000000-0000-4000-8000-00000000001", "a%20b", "caf%C3%A9"]])
case("banner_court_is_unknown_once_removed", [patch(bp("court"), True)], scenario="no_default_no_court")
for n, shown in [("absent", "__absent__"), ("string", "true"), ("null", None), ("number", 1), ("object", {}), ("array", [True])]:
    case("banner_patch_shown_" + n, [step("PATCH", bp("night"), {} if shown == "__absent__" else {"shown": shown})])
for n, raw in [("empty", ""), ("not_json", "not json"), ("array", "[]"), ("null", "null"), ("trailing_text", '{"shown":true} x')]:
    case("banner_patch_body_" + n, [patch(bp("night"), raw=raw)])
case("banner_a_bad_body_beats_an_unknown_id", [patch(bp("nope"), raw="not json"), step("PATCH", bp("nope"), {"shown": "yes"})])
case("banner_patch_ignores_unknown_fields", [step("PATCH", bp("dusk"), {"shown": False, "isDefault": True, "id": "x", "number": 99})])

# ---- banners: DELETE ----
case("banner_delete_a_hidden_one", [delete(bp("ember"))])
case("banner_delete_a_shown_one", [delete(bp("dusk"))])
case("banner_delete_an_upload", [delete(bp(B(1))), delete(bp(B(2)))])
case("banner_delete_the_default_is_refused", [delete(bp("court"))])
case("banner_delete_a_shown_one_at_the_minimum_is_refused", [delete(bp("night"))], scenario="two_shown")
case("banner_delete_a_hidden_one_at_the_minimum", [delete(bp("ember"))], scenario="two_shown")
case("banner_the_default_refusal_comes_first_on_delete", [delete(bp("court"))], scenario="two_shown")
case("banner_delete_twice", [delete(bp("ember")), delete(bp("ember"))])
case("banner_delete_a_deleted_one", [delete(bp("stripe"))])
case("banner_delete_unknown", [delete(bp("nope")), delete(bp("Court")), delete(bp("a%20b"))])
case("banner_delete_ignores_a_body", [step("DELETE", bp("ember"), {"shown": True})])
case("banner_delete_then_restore", [delete(bp("dusk")), restore(bp("dusk"))])
case("banner_delete_the_old_default_after_a_new_one", [default(bp("night")), delete(bp("court"))])

# ---- banners: restore ----
case("banner_restore_a_deleted_one", [restore(bp("stripe"))])
case("banner_restore_a_deleted_hidden_upload", [restore(bp(B(3)))])
case("banner_restore_twice", [restore(bp("stripe")), restore(bp("stripe"))])
case("banner_restore_one_that_is_back", [restore(bp("night")), restore(bp(B(2)))])
case("banner_restore_unknown", [restore(bp("nope")), restore(bp("Court")), restore(bp("a%20b")), restore(bp(B(9)))])
case("banner_restore_ignores_a_body", [step("POST", bp("stripe") + "/restore", raw="not json")])
case("banner_restore_by_the_second_admin", [restore(bp("stripe"), who=SECOND)])

# ---- banners: make default ----
case("banner_make_default", [default(bp("night"))])
case("banner_make_default_an_upload", [default(bp(B(1)))])
case("banner_make_default_again_changes_nothing", [default(bp("night")), default(bp("night"))])
case("banner_make_default_then_undo", [default(bp("night")), default(bp("court"))])
case("banner_make_default_that_is_the_default", [default(bp("court"))])
case("banner_make_default_a_hidden_one_is_refused", [default(bp("ember")), default(bp(B(2)))])
case("banner_make_default_a_deleted_one", [default(bp("stripe"))])
case("banner_make_default_unknown", [default(bp("nope")), default(bp("Court")), default(bp("a%20b"))])
case("banner_make_default_with_no_default", [default(bp("night"))], scenario="no_default")
case("banner_make_default_with_no_default_and_no_court", [default(bp("night"))], scenario="no_default_no_court")
case("banner_make_default_court_with_no_default", [default(bp("court"))], scenario="no_default")
case("banner_make_default_ignores_a_body", [step("POST", bp("night") + "/default", raw="not json")])
case("banner_make_default_by_the_second_admin", [default(bp("night"), who=SECOND)])
case("banner_hidden_default_after_the_default_moved", [default(bp("night")), patch(bp("court"), False)])

# ---- banners: two at once (the library lock lets one in at a time) ----
# The answers do not depend on who wins. The admin shown on the audit event does, so a race of two admins redacts it.
case("banner_race_two_hides_of_one", [{"parallel": [patch(bp("dusk"), False), patch(bp("dusk"), False)]}])
case("banner_race_two_hides_of_one_by_two_admins", [{"parallel": [patch(bp("dusk"), False), patch(bp("dusk"), False, who=SECOND)]}],
     redact={"admin_audit_events": ["actor_admin_id"]})
case("banner_race_two_deletes_of_one", [{"parallel": [delete(bp("dusk")), delete(bp("dusk"))]}])
case("banner_race_two_restores_of_one", [{"parallel": [restore(bp("stripe")), restore(bp("stripe"))]}])
case("banner_race_two_default_sets_of_one", [{"parallel": [default(bp("night")), default(bp("night"))]}])

# ---- characters: PATCH ----
case("character_hide_one", [patch(cp("a"), False)])
case("character_hide_the_one_with_the_empty_id", [patch(cp("_"), False)])
case("character_show_one", [patch(cp(C(2)), True)])
case("character_hide_an_upload", [patch(cp(C(1)), False)])
case("character_hide_then_show_again", [patch(cp("a"), False), patch(cp("a"), True)])
case("character_same_value_changes_nothing", [patch(cp("a"), True), patch(cp(C(2)), False)])
case("character_hide_at_the_minimum_is_refused", [patch(cp("a"), False)], scenario="fifteen_shown")
case("character_hide_a_hidden_one_at_the_minimum", [patch(cp(C(2)), False)], scenario="fifteen_shown")
case("character_show_at_the_minimum", [patch(cp(C(2)), True)], scenario="fifteen_shown")
case("character_hide_down_to_the_minimum", [patch(cp(i), False) for i in ["n", "o", "p", C(1), "m"]])
case("character_unknown_id", [patch(cp("q"), True), patch(cp("z"), True)])
case("character_deleted_id", [patch(cp(C(3)), True)])
case("character_id_formats_are_not_in_the_library", [patch(cp(i), True) for i in ["A", "ab", "1", "a-b", C(1).upper(), "c1000000-0000-4000-8000-00000000001", "a%20b", "caf%C3%A9"]])
for n, shown in [("absent", "__absent__"), ("string", "true"), ("null", None), ("number", 0), ("object", {})]:
    case("character_patch_shown_" + n, [step("PATCH", cp("a"), {} if shown == "__absent__" else {"shown": shown})])
for n, raw in [("empty", ""), ("not_json", "not json"), ("array", "[]"), ("null", "null"), ("trailing_text", '{"shown":true} x')]:
    case("character_patch_body_" + n, [patch(cp("a"), raw=raw)])
case("character_a_bad_body_beats_an_unknown_id", [patch(cp("z"), raw="not json"), step("PATCH", cp("z"), {"shown": "yes"})])
case("character_patch_ignores_unknown_fields", [step("PATCH", cp("a"), {"shown": False, "number": 99, "id": "x"})])

# ---- characters: DELETE ----
case("character_delete_a_shown_one", [delete(cp("a"))])
case("character_delete_the_one_with_the_empty_id", [delete(cp("_"))])
case("character_delete_a_hidden_one", [delete(cp(C(2)))])
case("character_delete_an_upload", [delete(cp(C(1)))])
case("character_delete_a_shown_one_at_the_minimum_is_refused", [delete(cp("a"))], scenario="fifteen_shown")
case("character_delete_a_hidden_one_at_the_minimum", [delete(cp(C(2)))], scenario="fifteen_shown")
case("character_delete_twice", [delete(cp("a")), delete(cp("a"))])
case("character_delete_a_deleted_one", [delete(cp(C(3)))])
case("character_delete_unknown", [delete(cp("z")), delete(cp("A")), delete(cp("a%20b"))])
case("character_delete_ignores_a_body", [step("DELETE", cp("a"), {"shown": True})])
case("character_delete_then_restore", [delete(cp("a")), restore(cp("a"))])
case("character_delete_down_to_the_minimum", [delete(cp(i)) for i in ["n", "o", "p", C(1), "m"]])

# ---- characters: restore ----
case("character_restore_a_deleted_one", [restore(cp(C(3)))])
case("character_restore_twice", [restore(cp(C(3))), restore(cp(C(3)))])
case("character_restore_one_that_is_back", [restore(cp("a")), restore(cp("_")), restore(cp(C(2)))])
case("character_restore_unknown", [restore(cp("z")), restore(cp("A")), restore(cp("a%20b")), restore(cp(C(9)))])
case("character_restore_ignores_a_body", [step("POST", cp(C(3)) + "/restore", raw="not json")])
case("character_restore_by_the_second_admin", [restore(cp(C(3)), who=SECOND)])
case("character_restore_the_empty_id_after_a_delete", [delete(cp("_")), restore(cp("_"))])

# ---- characters: two at once ----
case("character_race_two_hides_of_one", [{"parallel": [patch(cp("a"), False), patch(cp("a"), False)]}])
case("character_race_two_deletes_of_one", [{"parallel": [delete(cp("a")), delete(cp("a"))]}])
case("character_race_two_restores_of_one", [{"parallel": [restore(cp(C(3))), restore(cp(C(3)))]}])

# ---- both libraries at once (separate locks) ----
case("both_libraries_at_once", [{"parallel": [patch(bp("dusk"), False), patch(cp("a"), False)]}])

out = {
    "now": "2026-11-19T04:00:00.000Z",
    "app": "admin",
    "seed": "profiles.seed.sql",
    "scenarios": {
        "base": [],
        "two_shown": ["UPDATE profile_banners SET shown = false WHERE id IN ('dusk', '%s')" % B(1)],
        "three_shown": ["UPDATE profile_banners SET shown = false WHERE id = '%s'" % B(1)],
        "no_default": ["UPDATE profile_banners SET is_default = false"],
        "night_default": ["UPDATE profile_banners SET is_default = false WHERE id = 'court'", "UPDATE profile_banners SET is_default = true WHERE id = 'night'"],
        "no_default_no_court": ["DELETE FROM profile_banners WHERE id = 'court'"],
        "fifteen_shown": ["UPDATE profile_characters SET shown = false WHERE id IN ('n', 'o', 'p')"],
    },
    "snapshot": [
        {"name": "profile_banners", "sql": "SELECT id, image, shown, uploaded_at, number, deleted_at, is_default FROM profile_banners ORDER BY id", "redact": []},
        {"name": "profile_characters", "sql": "SELECT id, image, shown, uploaded_at, number, deleted_at FROM profile_characters ORDER BY id", "redact": []},
        {"name": "admin_audit_events", "sql": "SELECT id, actor_admin_id, action, target_type, target_id, source_command_id, occurred_at, metadata FROM admin_audit_events ORDER BY action, target_id, occurred_at, metadata::text", "redact": ["id"]},
        {"name": "player_notifications", "sql": "SELECT id FROM player_notifications ORDER BY id", "redact": []},
    ],
    "cases": cases,
}
with open(os.path.join(OUT, "profiles.cases.json"), "w") as f:
    json.dump(out, f, indent=2, ensure_ascii=False)
    f.write("\n")
print(len(cases), "cases")
